(function () {
  'use strict';

  var STORAGE_KEY = 'todos-vanilla';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  var todoApp = document.querySelector('.todoapp');
  var newTodo = document.querySelector('.new-todo');
  var toggleAll = document.getElementById('toggle-all');
  var todoList = document.querySelector('.todo-list');
  var footer = document.querySelector('.footer');
  var main = document.querySelector('.main');
  var todoCount = document.querySelector('.todo-count');
  var clearCompleted = document.querySelector('.clear-completed');
  var filters = document.querySelector('.filters');

  var todos = [];
  var nowShowing = 'all';

  function uuid() {
    var i, d = Date.now();
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
      i = (d + Math.random() * 16) % 16 | 0;
      d = Math.floor(d / 16);
      return (c === 'x' ? i : (i & 0x3) | 0x8).toString(16);
    });
  }

  function loadTodos() {
    try {
      var data = localStorage.getItem(STORAGE_KEY);
      todos = data ? JSON.parse(data) : [];
    } catch (e) {
      todos = [];
    }
  }

  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function getFilteredTodos() {
    if (nowShowing === 'active') return todos.filter(function (t) { return !t.completed; });
    if (nowShowing === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  function pluralize(count, word) {
    return count === 1 ? word : word + 's';
  }

  function todoId(el) {
    var li = el && el.closest ? el.closest('li') : null;
    return li ? li.dataset.id : null;
  }

  function findTodoIndex(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) return i;
    }
    return -1;
  }

  function render() {
    var filtered = getFilteredTodos();
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var completedCount = todos.length - activeCount;

    todoList.innerHTML = '';
    filtered.forEach(function (todo) {
      var li = document.createElement('li');
      li.dataset.id = todo.id;
      if (todo.completed) li.className = 'completed';
      li.innerHTML =
        '<div class="view">' +
          '<input class="toggle" type="checkbox" ' + (todo.completed ? 'checked' : '') + '>' +
          '<label>' + escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeHtml(todo.title) + '">';
      todoList.appendChild(li);
    });

    main.style.display = todos.length > 0 ? '' : 'none';
    footer.style.display = todos.length > 0 ? '' : 'none';

    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + activeCount + ' ' + pluralize(activeCount, 'item') + ' left';

    clearCompleted.style.display = completedCount > 0 ? '' : 'none';
    clearCompleted.textContent = 'Clear completed';

    toggleAll.checked = activeCount === 0 && todos.length > 0;

    var filterLinks = filters.querySelectorAll('a');
    filterLinks.forEach(function (a) {
      var href = a.getAttribute('href');
      if (href === '#/' + (nowShowing === 'all' ? '' : nowShowing === 'active' ? 'active' : 'completed')) {
        a.className = 'selected';
      } else {
        a.className = '';
      }
    });

    if (nowShowing === 'all') {
      var allLink = filters.querySelector('a[href="#/"]');
      if (allLink) allLink.className = 'selected';
    }
  }

  function escapeHtml(s) {
    return String(s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function addTodo(title) {
    var trimmed = title.trim();
    if (!trimmed) return;
    todos.push({ id: uuid(), title: trimmed, completed: false });
    saveTodos();
    render();
  }

  function toggleTodo(id) {
    var idx = findTodoIndex(id);
    if (idx === -1) return;
    todos[idx].completed = !todos[idx].completed;
    saveTodos();
    render();
  }

  function destroyTodo(id) {
    var idx = findTodoIndex(id);
    if (idx === -1) return;
    todos.splice(idx, 1);
    saveTodos();
    render();
  }

  function toggleAllTodos(checked) {
    todos.forEach(function (t) { t.completed = checked; });
    saveTodos();
    render();
  }

  function clearCompletedTodos() {
    todos = todos.filter(function (t) { return !t.completed; });
    saveTodos();
    render();
  }

  function editTodo(id, title) {
    var idx = findTodoIndex(id);
    if (idx === -1) return;
    var trimmed = title.trim();
    if (trimmed) {
      todos[idx].title = trimmed;
      saveTodos();
      render();
    } else {
      destroyTodo(id);
    }
  }

  function cancelEdit(id) {
    render();
  }

  function setRoute(route) {
    nowShowing = route;
    render();
  }

  // --- Event handlers ---

  newTodo.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      addTodo(newTodo.value);
      newTodo.value = '';
    }
  });

  todoList.addEventListener('change', function (e) {
    if (e.target.classList.contains('toggle')) {
      var id = todoId(e.target);
      if (id) toggleTodo(id);
    }
  });

  todoList.addEventListener('click', function (e) {
    if (e.target.classList.contains('destroy')) {
      var id = todoId(e.target);
      if (id) destroyTodo(id);
    }
  });

  todoList.addEventListener('dblclick', function (e) {
    var label = e.target.closest && e.target.closest('label');
    if (!label) return;
    var li = label.closest('li');
    if (!li) return;
    li.className = 'editing';
    var editInput = li.querySelector('.edit');
    if (editInput) {
      editInput.focus();
      editInput.selectionStart = editInput.selectionEnd = editInput.value.length;
    }
  });

  todoList.addEventListener('keydown', function (e) {
    var editInput = e.target.closest && e.target.closest('.edit');
    if (!editInput) return;
    var li = editInput.closest('li');
    if (!li) return;
    var id = li.dataset.id;
    if (e.keyCode === ENTER_KEY) {
      editTodo(id, editInput.value);
    } else if (e.keyCode === ESCAPE_KEY) {
      li.className = li.className.replace(/\bediting\b/g, '').trim();
      cancelEdit(id);
    }
  });

  todoList.addEventListener('blur', function (e) {
    var editInput = e.target.closest && e.target.closest('.edit');
    if (!editInput) return;
    var li = editInput.closest('li');
    if (!li) return;
    if (li.className.indexOf('editing') === -1) return;
    var id = li.dataset.id;
    editTodo(id, editInput.value);
  }, true);

  toggleAll.addEventListener('change', function (e) {
    toggleAllTodos(e.target.checked);
  });

  clearCompleted.addEventListener('click', function () {
    clearCompletedTodos();
  });

  // --- Routing ---

  window.addEventListener('hashchange', function () {
    var route = window.location.hash.replace('#/', '') || 'all';
    setRoute(route);
  });

  // --- Init ---

  loadTodos();

  var initialRoute = window.location.hash.replace('#/', '') || 'all';
  nowShowing = initialRoute;
  render();
})();

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('node:assert');

// ===== GIVEN =====

Given('the app is loaded', function () {
  // The Before hook in world.js already calls loadApp()
});

Given('there are no todos', function () {
  // App starts with no todos by default after reload.
  // Verify no todo items exist.
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, 0);
});

Given('the todo list has a todo {string}', function (title) {
  addTodoViaDOM(this.document, this.window, title);
});

Given('the todo list has todos: {string}', function (titles) {
  const list = titles.split(',').map(s => s.trim());
  list.forEach(t => addTodoViaDOM(this.document, this.window, t));
});

Given('all todos are completed', function () {
  const toggleAll = this.document.getElementById('toggle-all');
  if (toggleAll && !toggleAll.checked) {
    toggleAll.click();
  }
  // Ensure all todos are completed
  const items = this.document.querySelectorAll('.todo-list li');
  items.forEach(li => {
    if (!li.classList.contains('completed')) {
      const toggle = li.querySelector('.toggle');
      if (toggle) toggle.click();
    }
  });
});

// ===== WHEN =====

When('I type {string} into the new-todo input', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  // Simulate input event
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('I press Enter', function () {
  const input = this.document.querySelector('.new-todo');
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    keyCode: 13,
    key: 'Enter',
    bubbles: true
  }));
});

When('I click the toggle-all checkbox', function () {
  const checkbox = this.document.getElementById('toggle-all');
  checkbox.click();
});

When('I click the toggle for {string}', function (title) {
  const toggle = findToggleForTodo(this.document, title);
  if (!toggle) throw new Error('Toggle not found for todo: ' + title);
  toggle.click();
});

When('I double-click the label for {string}', function (title) {
  const label = findLabelForTodo(this.document, title);
  if (!label) throw new Error('Label not found for todo: ' + title);
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

When('I click the destroy button for {string}', function (title) {
  const destroy = findDestroyForTodo(this.document, title);
  if (!destroy) throw new Error('Destroy button not found for todo: ' + title);
  destroy.click();
});

When('I complete the todo {string}', function (title) {
  const toggle = findToggleForTodo(this.document, title);
  if (!toggle) throw new Error('Toggle not found for todo: ' + title);
  toggle.click();
});

When('I start editing {string}', function (title) {
  const label = findLabelForTodo(this.document, title);
  if (!label) throw new Error('Label not found for todo: ' + title);
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

When('I change the edit value to {string}', function (value) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No editing input found');
  editInput.value = value;
  editInput.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('I press Enter while editing', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No editing input found');
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    keyCode: 13,
    key: 'Enter',
    bubbles: true
  }));
});

When('I blur the edit input', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No editing input found');
  editInput.dispatchEvent(new this.window.FocusEvent('blur', { bubbles: true }));
});

When('I press Escape while editing', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No editing input found');
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    keyCode: 27,
    key: 'Escape',
    bubbles: true
  }));
});

When('I click {string}', function (buttonText) {
  if (buttonText === 'Clear completed') {
    const btn = this.document.querySelector('.clear-completed');
    if (!btn) throw new Error('Clear completed button not found');
    btn.click();
  } else {
    const btn = Array.from(this.document.querySelectorAll('button')).find(
      b => b.textContent.trim() === buttonText
    );
    if (!btn) throw new Error('Button not found: ' + buttonText);
    btn.click();
  }
});

When('the page is reloaded', function () {
  // Persist current localStorage data, dispose, and reload
  const data = this.localStorage.getItem('todos-vanilla');
  this.disposeApp();
  this.loadApp();
  // Restore localStorage
  if (data) {
    this.localStorage.setItem('todos-vanilla', data);
  }
  // The app loads from localStorage on init
});

When('the route is {string}', function (route) {
  // Normalize: "#/", "#/active", "#/completed"
  let hash = route;
  if (hash === '#/' || hash === '#/all' || hash === 'all' || hash === '') hash = '#/';
  else if (hash.startsWith('#')) { /* keep as is */ }
  else if (hash.startsWith('/')) hash = '#' + hash;
  else hash = '#/' + hash;
  this.navigate(hash);
});

// ===== THEN =====

Then('{string} is not visible', function (selector) {
  const el = this.document.querySelector(selector);
  if (!el) return; // Not in DOM = not visible
  const display = this.window.getComputedStyle(el).display;
  assert.strictEqual(display, 'none', 'Expected ' + selector + ' to have display:none, got: ' + display);
});

Then('{string} is visible', function (selector) {
  const el = this.document.querySelector(selector);
  if (!el) throw new Error('Element not found: ' + selector);
  const display = this.window.getComputedStyle(el).display;
  assert.notStrictEqual(display, 'none', 'Expected ' + selector + ' to be visible, got display:none');
});

Then('the todo list contains a todo titled {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  const titles = Array.from(items).map(li => {
    const label = li.querySelector('label');
    return label ? label.textContent.trim() : '';
  });
  assert.ok(titles.includes(title), 'Expected todo list to contain "' + title + '", got: ' + JSON.stringify(titles));
});

Then('the new-todo input is cleared', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(input.value, '');
});

Then('the todo list is empty', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, 0);
});

Then('the new-todo input has focus', function () {
  const input = this.document.querySelector('.new-todo');
  const active = this.document.activeElement;
  assert.strictEqual(active, input, 'Expected new-todo input to have focus');
});

Then('all todos have class {string}', function (className) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length > 0, 'No todo items found');
  Array.from(items).forEach(li => {
    assert.ok(li.classList.contains(className), 'Expected todo to have class "' + className + '"');
  });
});

Then('no todos have class {string}', function (className) {
  const items = this.document.querySelectorAll('.todo-list li');
  Array.from(items).forEach(li => {
    assert.ok(!li.classList.contains(className), 'Expected todo not to have class "' + className + '"');
  });
});

Then('the toggle-all checkbox is checked', function () {
  const checkbox = this.document.getElementById('toggle-all');
  assert.ok(checkbox, 'toggle-all checkbox not found');
  assert.strictEqual(checkbox.checked, true);
});

Then('the toggle-all checkbox is not checked', function () {
  const checkbox = this.document.getElementById('toggle-all');
  assert.ok(checkbox, 'toggle-all checkbox not found');
  assert.strictEqual(checkbox.checked, false);
});

Then('the todo {string} has class {string}', function (title, className) {
  const li = findLiForTodo(this.document, title);
  if (!li) throw new Error('Todo not found: ' + title);
  assert.ok(li.classList.contains(className), 'Expected todo "' + title + '" to have class "' + className + '"');
});

Then('the todo {string} has its checkbox checked', function (title) {
  const toggle = findToggleForTodo(this.document, title);
  if (!toggle) throw new Error('Toggle not found for todo: ' + title);
  assert.strictEqual(toggle.checked, true);
});

Then('the {string} todo item has class {string}', function (title, className) {
  const li = findLiForTodo(this.document, title);
  if (!li) throw new Error('Todo not found: ' + title);
  if (className.startsWith('does not have class')) {
    const cls = className.replace('does not have class', '').trim();
    assert.ok(!li.classList.contains(cls), 'Expected todo not to have class "' + cls + '"');
  } else if (className.startsWith('does not')) {
    const cls = className.replace('does not', '').trim();
    assert.ok(!li.classList.contains(cls), 'Expected todo not to have class "' + cls + '"');
  } else {
    assert.ok(li.classList.contains(className), 'Expected todo to have class "' + className + '"');
  }
