const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('node:assert');

// ===== Helper functions =====

function addTodoViaDOM(document, window, title) {
  var input = document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new window.Event('input', { bubbles: true }));
  input.dispatchEvent(new window.KeyboardEvent('keydown', {
    keyCode: 13, key: 'Enter', bubbles: true
  }));
}

function findLiForTodo(document, title) {
  var items = document.querySelectorAll('.todo-list li');
  return Array.from(items).find(function (li) {
    var label = li.querySelector('label');
    return label && label.textContent.trim() === title;
  }) || null;
}

function findToggleForTodo(document, title) {
  var li = findLiForTodo(document, title);
  return li ? li.querySelector('.toggle') : null;
}

function findLabelForTodo(document, title) {
  var li = findLiForTodo(document, title);
  return li ? li.querySelector('label') : null;
}

function findDestroyForTodo(document, title) {
  var li = findLiForTodo(document, title);
  return li ? li.querySelector('.destroy') : null;
}

// ===== GIVEN =====

Given('the app is loaded', function () {
  // The Before hook in world.js already calls loadApp()
});

Given('there are no todos', function () {
  var items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, 0);
});

Given('the todo list has a todo {string}', function (title) {
  addTodoViaDOM(this.document, this.window, title);
});

Given('the todo list has todos: {string}', function (titles) {
  var list = titles.split(',').map(function (s) { return s.trim(); });
  list.forEach(function (t) {
    addTodoViaDOM(this.document, this.window, t);
  }.bind(this));
});

Given('all todos are completed', function () {
  var items = this.document.querySelectorAll('.todo-list li');
  Array.from(items).forEach(function (li) {
    if (!li.classList.contains('completed')) {
      var toggle = li.querySelector('.toggle');
      if (toggle) toggle.click();
    }
  });
});

// ===== WHEN =====

When('I type {string} into the new-todo input', function (text) {
  var input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('I press Enter', function () {
  var input = this.document.querySelector('.new-todo');
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    keyCode: 13, key: 'Enter', bubbles: true
  }));
});

When('I click the toggle-all checkbox', function () {
  var checkbox = this.document.getElementById('toggle-all');
  checkbox.click();
});

When('I click the toggle for {string}', function (title) {
  var toggle = findToggleForTodo(this.document, title);
  if (!toggle) throw new Error('Toggle not found for todo: ' + title);
  toggle.click();
});

When('I double-click the label for {string}', function (title) {
  var label = findLabelForTodo(this.document, title);
  if (!label) throw new Error('Label not found for todo: ' + title);
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

When('I click the destroy button for {string}', function (title) {
  var destroy = findDestroyForTodo(this.document, title);
  if (!destroy) throw new Error('Destroy button not found for todo: ' + title);
  destroy.click();
});

