});

When('I start editing {string}', function (title) {
  var label = findLabelForTodo(this.document, title);
  if (!label) throw new Error('Label not found for todo: ' + title);
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

When('I change the edit value to {string}', function (value) {
