  editInput.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('I press Enter while editing', function () {
  var editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No editing input found');
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    keyCode: 13, key: 'Enter', bubbles: true
  }));
});

When('I blur the edit input', function () {
  var editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No editing input found');
  editInput.dispatchEvent(new this.window.FocusEvent('blur', { bubbles: true }));
});

When('I press Escape while editing', function () {
  var editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No editing input found');
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    keyCode: 27, key: 'Escape', bubbles: true
  }));
});

When('I click {string}', function (buttonText) {
