  } else {
    var btn = Array.from(this.document.querySelectorAll('button')).find(
      function (b) { return b.textContent.trim() === buttonText; }
    );
    if (!btn) throw new Error('Button not found: ' + buttonText);
    btn.click();
  }
});

When('the page is reloaded', function () {
  var data = this.localStorage.getItem('todos-vanilla');
