  this.loadApp();
  if (data) {
    this.localStorage.setItem('todos-vanilla', data);
  }
});

When('the route is {string}', function (route) {
  var hash = route;
  if (hash === '#/' || hash === '#/all' || hash === 'all' || hash === '') hash = '#/';
  else if (hash.startsWith('#')) { /* keep */ }
  else if (hash.startsWith('/')) hash = '#' + hash;
  else hash = '#/' + hash;
