});

Then('the {string} button is not visible', function (buttonText) {
  var btn;
  if (buttonText === 'Clear completed') {
    btn = this.document.querySelector('.clear-completed');
  } else {
    btn = Array.from(this.document.querySelectorAll('button')).find(
      function (b) { return b.textContent.trim() === buttonText; }
    );
