  if (!li) throw new Error('Todo not found: ' + title);
  var label = li.querySelector('label');
  assert.ok(label, 'Label not found for todo');
  assert.strictEqual(label.textContent.trim(), expectedTitle);
});

Then('the todo {string} is in the list', function (title) {
  var li = findLiForTodo(this.document, title);
  assert.ok(li, 'Expected todo "' + title + '" to be in the list');
});

